import React, { useState } from 'react';
import { FaQuoteLeft, FaStar, FaChevronLeft, FaChevronRight } from 'react-icons/fa';

const testimonialsData = [
    {
        id: 1,
        name: "Sarah Johnson",
        position: "Product Manager",
        company: "TechCorp Solutions",
        image: "https://images.unsplash.com/photo-1494790108755-2616b612b786?w=150&h=150&fit=crop&crop=face",
        rating: 5,
        testimonial: "Amulya is an exceptional developer who consistently delivers high-quality solutions. His attention to detail and ability to understand complex requirements made our project a huge success. The microservices architecture he designed improved our system performance by 45%.",
        project: "E-Commerce Platform Redesign"
    },
    {
        id: 2,
        name: "Michael Chen",
        position: "Senior Frontend Developer",
        company: "Digital Innovations Ltd",
        image: "https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=150&h=150&fit=crop&crop=face",
        rating: 5,
        testimonial: "Working alongside Amulya was a pleasure. His React expertise and problem-solving skills are top-notch. He mentored our junior developers and helped establish coding best practices that we still follow today.",
        project: "Social Media Dashboard"
    },
    {
        id: 3,
        name: "Emily Rodriguez",
        position: "UI/UX Designer",
        company: "Creative Studios",
        image: "https://images.unsplash.com/photo-1438761681033-6461ffad8d80?w=150&h=150&fit=crop&crop=face",
        rating: 5,
        testimonial: "Amulya brings designs to life with pixel-perfect precision. His understanding of user experience and ability to implement complex animations and interactions is remarkable. Our collaboration resulted in a 25% increase in user engagement.",
        project: "Mobile App Development"
    },
    {
        id: 4,
        name: "David Kumar",
        position: "CTO",
        company: "StartupXYZ",
        image: "https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=150&h=150&fit=crop&crop=face",
        rating: 5,
        testimonial: "Amulya's full-stack capabilities are impressive. He developed our entire web application from scratch and delivered it ahead of schedule. His code quality and documentation standards are exceptional.",
        project: "Task Management Platform"
    },
    {
        id: 5,
        name: "Lisa Thompson",
        position: "Project Manager",
        company: "Innovation Labs",
        image: "https://images.unsplash.com/photo-1544725176-7c40e5a71c5e?w=150&h=150&fit=crop&crop=face",
        rating: 5,
        testimonial: "Amulya's technical skills combined with his excellent communication made him an invaluable team member. He consistently met deadlines and provided creative solutions to complex challenges.",
        project: "AI Chatbot Integration"
    }
];

function Testimonials() {
    const [currentIndex, setCurrentIndex] = useState(0);

    const nextTestimonial = () => {
        setCurrentIndex((prev) => (prev + 1) % testimonialsData.length);
    };

    const prevTestimonial = () => {
        setCurrentIndex((prev) => (prev - 1 + testimonialsData.length) % testimonialsData.length);
    };

    const currentTestimonial = testimonialsData[currentIndex];

    return (
        <section id="testimonials" className="py-20 px-6 sm:px-8 lg:px-12 bg-gradient-to-br from-[#20262E] to-[#1a1f26]">
            <div className="max-w-7xl mx-auto">
                {/* Section Header */}
                <div className="text-center mb-16">
                    <h2 className="text-4xl sm:text-5xl md:text-6xl font-bold text-white mb-6">
                        What People <span className="text-[#6699CC]">Say</span>
                    </h2>
                    <div className="w-24 h-1 bg-[#6699CC] mx-auto rounded-full mb-8"></div>
                    <p className="text-gray-300 text-xl max-w-3xl mx-auto leading-relaxed">
                        Feedback from clients, colleagues, and team members I've had the pleasure of working with
                    </p>
                </div>

                {/* Main Testimonial Display */}
                <div className="max-w-4xl mx-auto">
                    <div className="bg-gray-800/50 rounded-3xl border border-gray-700/50 p-8 md:p-12 relative">
                        {/* Quote Icon */}
                        <FaQuoteLeft className="text-[#6699CC] text-4xl mb-6" />
                        
                        {/* Testimonial Content */}
                        <blockquote className="text-gray-300 text-lg md:text-xl leading-relaxed mb-8 italic">
                            "{currentTestimonial.testimonial}"
                        </blockquote>
                        
                        {/* Rating */}
                        <div className="flex items-center space-x-1 mb-6">
                            {[...Array(5)].map((_, i) => (
                                <FaStar 
                                    key={i} 
                                    className={`${i < currentTestimonial.rating ? 'text-yellow-400' : 'text-gray-600'}`} 
                                />
                            ))}\n                        </div>
                        
                        {/* Author Info */}
                        <div className="flex items-center justify-between">
                            <div className="flex items-center space-x-4">
                                <img 
                                    src={currentTestimonial.image} 
                                    alt={currentTestimonial.name}
                                    className="w-16 h-16 rounded-full border-2 border-[#6699CC]"
                                />
                                <div>
                                    <h4 className="text-white font-semibold text-lg">{currentTestimonial.name}</h4>
                                    <p className="text-[#6699CC]">{currentTestimonial.position}</p>
                                    <p className="text-gray-400 text-sm">{currentTestimonial.company}</p>
                                    <p className="text-gray-500 text-xs mt-1">Project: {currentTestimonial.project}</p>
                                </div>
                            </div>
                            
                            {/* Navigation */}
                            <div className="flex space-x-4">
                                <button 
                                    onClick={prevTestimonial}
                                    className="w-12 h-12 bg-gray-700/50 hover:bg-[#6699CC]/20 rounded-full flex items-center justify-center transition-all duration-300 group"
                                >
                                    <FaChevronLeft className="text-gray-400 group-hover:text-[#6699CC]" />
                                </button>
                                <button 
                                    onClick={nextTestimonial}
                                    className="w-12 h-12 bg-gray-700/50 hover:bg-[#6699CC]/20 rounded-full flex items-center justify-center transition-all duration-300 group"
                                >
                                    <FaChevronRight className="text-gray-400 group-hover:text-[#6699CC]" />
                                </button>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Testimonial Indicators */}
                <div className="flex justify-center space-x-3 mt-8">
                    {testimonialsData.map((_, index) => (
                        <button
                            key={index}
                            onClick={() => setCurrentIndex(index)}
                            className={`w-3 h-3 rounded-full transition-all duration-300 ${
                                index === currentIndex ? 'bg-[#6699CC]' : 'bg-gray-600 hover:bg-gray-500'
                            }`}
                        />
                    ))}
                </div>

                {/* All Testimonials Grid (Mini Cards) */}
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mt-16">
                    {testimonialsData.slice(0, 3).map((testimonial, index) => (
                        <div key={testimonial.id} className="bg-gray-800/30 rounded-xl p-6 border border-gray-700/30 hover:border-[#6699CC]/50 transition-all duration-300">
                            <div className="flex items-center space-x-3 mb-4">
                                <img 
                                    src={testimonial.image} 
                                    alt={testimonial.name}
                                    className="w-12 h-12 rounded-full border-2 border-[#6699CC]"
                                />
                                <div>
                                    <h5 className="text-white font-semibold">{testimonial.name}</h5>
                                    <p className="text-gray-400 text-sm">{testimonial.company}</p>
                                </div>
                            </div>
                            <p className="text-gray-300 text-sm leading-relaxed">
                                "{testimonial.testimonial.substring(0, 120)}..."
                            </p>
                            <div className="flex items-center space-x-1 mt-3">
                                {[...Array(5)].map((_, i) => (
                                    <FaStar 
                                        key={i} 
                                        className={`text-sm ${i < testimonial.rating ? 'text-yellow-400' : 'text-gray-600'}`} 
                                    />
                                ))}
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </section>
    );
}

export default Testimonials;
